1	package tariff
2	
3	import (
4		"errors"
5		"math"
6		"testing"
7	)
8	
9	// TestItemOutcomesListsConfirmationsAndRejections 覆盖按费率项查看已受理报价的
10	// 核心场景：确认与拒绝都列出；旧版确认价不被当前费率重算；
11	// 失效后引用旧版的拒绝与旧确认同时保留；排序按首次受理时刻、再按请求标识。
12	func TestItemOutcomesListsConfirmationsAndRejections(t *testing.T) {
13		now, setNow := fixedClock(at(1))
14		b := NewBook(WithClock(now))
15		mustReg := func(r RegisterRequest) {
16			t.Helper()
17			if err := b.RegisterVersion(r); err != nil {
18				t.Fatalf("register %+v: %v", r, err)
